import React, { useState, useEffect } from 'react';
import { dashboardApi } from '../api/client';
import {
  PlayCircle,
  PauseCircle,
  Wrench,
  AlertTriangle,
  Gauge,
  Award,
  Zap,
  TrendingUp,
  Clock,
} from 'lucide-react';
import { useNavigate } from 'react-router-dom';

const SystemStatusBar = () => {
  const navigate = useNavigate();
  const [hoveredKpi, setHoveredKpi] = useState(null);
  const [summaryData, setSummaryData] = useState(null);

  useEffect(() => {
    fetchSummary();
  }, []);

  const fetchSummary = async () => {
    try {
      const res = await dashboardApi.getSummary();
      if (res && res.data && res.data.success) {
        setSummaryData(res.data.data);
      }
    } catch (err) {
      console.error('Failed to fetch summary:', err);
    }
  };

  const kpis = [
    {
      key: 'running',
      title: 'Running Machines',
      value: summaryData ? `${summaryData.running} / ${summaryData.totalAssets || 20}` : '16 / 20',
      status: '90% Operational',
      lastUpdated: '2 sec ago',
      icon: PlayCircle,
      color: '#16A34A',
      bg: '#DCFCE7',
      borderColor: '#BBF7D0',
      route: '/factory/running-machines',
    },
    {
      key: 'idle',
      title: 'Idle Machines',
      value: summaryData ? `${summaryData.idle}` : '2',
      status: 'Standby',
      lastUpdated: 'Just now',
      icon: PauseCircle,
      color: '#D97706',
      bg: '#FEF3C7',
      borderColor: '#FDE68A',
      route: '/factory/idle-machines',
    },
    {
      key: 'maintenance',
      title: 'Scheduled Maintenance',
      value: summaryData ? `${summaryData.maintenance}` : '2',
      status: 'Scheduled Service',
      lastUpdated: '1 min ago',
      icon: Wrench,
      color: '#EA580C',
      bg: '#FFEDD5',
      borderColor: '#FED7AA',
      route: '/maintenance',
    },
    {
      key: 'alerts',
      title: 'Critical Alerts',
      value: summaryData ? `${summaryData.highCriticality}` : '3',
      status: 'Immediate Action Required',
      lastUpdated: '5 sec ago',
      icon: AlertTriangle,
      color: '#DC2626',
      bg: '#FEE2E2',
      borderColor: '#FECACA',
      route: '/alerts',
    },
    {
      key: 'production',
      title: "Today's Production",
      value: '14,250 m',
      status: 'Target 16,000 m (89%)',
      lastUpdated: 'Real-time',
      icon: Gauge,
      color: '#2563EB',
      bg: '#DBEAFE',
      borderColor: '#BFDBFE',
      route: '/analytics/production',
    },
    {
      key: 'oee',
      title: 'OEE',
      value: '96.4%',
      status: 'World Class',
      lastUpdated: '10 sec ago',
      icon: Award,
      color: '#7C3AED',
      bg: '#F3E8FF',
      borderColor: '#DDD6FE',
      route: '/analytics/oee',
    },
    {
      key: 'energy',
      title: 'Energy Consumption',
      value: '1,245 kWh',
      status: 'Optimal Consumption',
      lastUpdated: '3 sec ago',
      icon: Zap,
      color: '#059669',
      bg: '#ECFDF5',
      borderColor: '#A7F3D0',
      route: '/analytics/energy',
    },
  ];

  return (
    <section style={{ width: '100%', marginBottom: '1.75rem' }}>
      {/* Full-Width Enterprise Clickable KPI Cards */}
      <div
        style={{
          display: 'grid',
          gridTemplateColumns: 'repeat(auto-fit, minmax(260px, 1fr))',
          gap: '1.25rem',
          width: '100%',
        }}
      >
        {kpis.map((kpi) => {
          const CardIcon = kpi.icon;
          const isHovered = hoveredKpi === kpi.key;

          return (
            <div
              key={kpi.key}
              onClick={() => navigate(kpi.route)}
              style={{
                background: '#ffffff',
                borderRadius: '14px',
                padding: '1.35rem 1.5rem',
                border: isHovered ? `2px solid ${kpi.color}` : `1px solid ${kpi.borderColor}`,
                boxShadow: isHovered
                  ? `0 10px 25px ${kpi.color}25`
                  : '0 4px 18px rgba(0, 0, 0, 0.03)',
                transform: isHovered ? 'translateY(-4px)' : 'none',
                display: 'flex',
                flexDirection: 'column',
                justifyContent: 'space-between',
                transition: 'all 0.25s cubic-bezier(0.4, 0, 0.2, 1)',
                minHeight: '160px',
                cursor: 'pointer',
                position: 'relative',
              }}
              onMouseEnter={() => setHoveredKpi(kpi.key)}
              onMouseLeave={() => setHoveredKpi(null)}
            >
              {/* Header: Status Icon & Card Title */}
              <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', gap: '0.75rem' }}>
                <div style={{ display: 'flex', alignItems: 'center', gap: '0.6rem' }}>
                  <div
                    style={{
                      width: '36px',
                      height: '36px',
                      borderRadius: '10px',
                      background: kpi.bg,
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center',
                      color: kpi.color,
                      flexShrink: 0,
                    }}
                  >
                    <CardIcon size={19} />
                  </div>
                  <span style={{ fontSize: '0.92rem', fontWeight: '800', color: '#334155', lineHeight: '1.3' }}>
                    {kpi.title}
                  </span>
                </div>
              </div>

              {/* Body: Value & Status Line */}
              <div style={{ marginTop: '0.85rem', marginBottom: '0.65rem' }}>
                <div
                  style={{
                    fontSize: '2rem',
                    fontWeight: '900',
                    color: '#0F172A',
                    lineHeight: '1.1',
                    letterSpacing: '-0.5px',
                    fontFamily: 'Plus Jakarta Sans, sans-serif',
                  }}
                >
                  {kpi.value}
                </div>

                <div
                  style={{
                    fontSize: '0.82rem',
                    fontWeight: '700',
                    color: kpi.color,
                    marginTop: '0.4rem',
                    display: 'flex',
                    alignItems: 'center',
                    gap: '0.35rem',
                  }}
                >
                  <TrendingUp size={13} /> {kpi.status}
                </div>
              </div>

              {/* Footer: Last Updated Timestamp */}
              <div
                style={{
                  paddingTop: '0.6rem',
                  borderTop: '1px solid #F1F5F9',
                  fontSize: '0.74rem',
                  color: '#94A3B8',
                  fontWeight: '600',
                  display: 'flex',
                  alignItems: 'center',
                  gap: '0.35rem',
                }}
              >
                <Clock size={12} /> Last Updated: {kpi.lastUpdated}
              </div>
            </div>
          );
        })}
      </div>
    </section>
  );
};

export default SystemStatusBar;
